  "/robots.txt": { type: "text/plain; charset=utf-8", body: "User-agent: *\nAllow: /\nDisallow: /report/\nDisallow: /trap.html\nDisallow: /trap2.html\nDisallow: /targets.html\nDisallow: /targets2.html\nDisallow: /partial-obscured.html\nDisallow: /nav-a.html\nDisallow: /nav-b.html\nSitemap: https://checker.lazynext.com/sitemap.xml\n" },
